-- deploy-gate: deferred بقرار D03، يُطبَّق بعد توقيع لجنة المحتوى ومراجع قياسي، بعد 20261105150000 وقبل التفعيل
-- مولَّد بـ scripts/questions/build-v5_2.mjs من supabase/content/questions/v5.1 وscripts/questions/edits-v5_2.mjs
-- 15 صفًا يتغير، والدرجات ومواضع المفاتيح ثابتة. الحارس: لا قياس مبدوء على الأداتين، ونص كل صف
-- المتغير هو نص v5.1 (بصمة md5 للجذع والخيارات)، وإلا يُرفض الترحيل كله. آمن لإعادة التشغيل.
do $$ begin
  if exists (select 1 from leaders.assessments a join leaders.instruments i on i.id = a.instrument_id where i.key in ('baseline-v5', 'post-v3')) then
    raise exception 'v5.2: لأداتي v5 قياسات مبدوءة؛ لا تُعدَّل فقراتهما بعد ذلك';
  end if;
  if not exists (select 1 from leaders.schema_migrations where name = '20261105150000_leaders_v5_1_pre_activation') then
    raise exception 'v5.2: طبّق 20261105150000_leaders_v5_1_pre_activation.sql أولًا';
  end if;
end $$;

-- baseline-v5/M-S2
update leaders.questions q set text_ar = 'في جلسة بوابة مرحلة: المشروع متأخر ثلاثة أسابيع، ومبرر الاستمرار قائم، والمخاطر معروفة. ما القرار الأنسب؟', options = '[{"label":"إعادة عقد الجلسة بعد أسبوعين وقد حُدّث الجدول","score":1},{"label":"عبور مع خطة تصحيح تُعرض في الاجتماع الدوري القادم","score":2},{"label":"عبور مع طلب اعتماد خط أساس معدل بالتاريخ الجديد","score":1},{"label":"عبور مشروط بخطة تصحيح ومعلم مراجعة خلال أسبوعين","score":4}]'::jsonb, chapter_key = 'ch4'
  from leaders.instruments i where i.id = q.instrument_id and i.key = 'baseline-v5' and q.code = 'M-S2'
  and ((q.text_ar = 'في جلسة بوابة مرحلة: المشروع متأخر ثلاثة أسابيع، ومبرر الاستمرار قائم، والمخاطر معروفة. ما القرار الأنسب؟' and q.options = '[{"label":"إعادة عقد الجلسة بعد أسبوعين وقد حُدّث الجدول","score":1},{"label":"عبور مع خطة تصحيح تُعرض في الاجتماع الدوري القادم","score":2},{"label":"عبور مع طلب اعتماد خط أساس معدل بالتاريخ الجديد","score":1},{"label":"عبور مشروط بخطة تصحيح ومعلم مراجعة خلال أسبوعين","score":4}]'::jsonb and q.chapter_key is not distinct from 'ch3') or (q.text_ar = 'في جلسة بوابة مرحلة: المشروع متأخر ثلاثة أسابيع، ومبرر الاستمرار قائم، والمخاطر معروفة. ما القرار الأنسب؟' and q.options = '[{"label":"إعادة عقد الجلسة بعد أسبوعين وقد حُدّث الجدول","score":1},{"label":"عبور مع خطة تصحيح تُعرض في الاجتماع الدوري القادم","score":2},{"label":"عبور مع طلب اعتماد خط أساس معدل بالتاريخ الجديد","score":1},{"label":"عبور مشروط بخطة تصحيح ومعلم مراجعة خلال أسبوعين","score":4}]'::jsonb and q.chapter_key is not distinct from 'ch4'));
