  and ((q.text_ar = 'في مراجعة مرحلية: المشروع ضمن الموعد، لكن دراسة حديثة تظهر أن الطلب على الخدمة أقل بكثير مما بُني عليه المبرر. ما القرار الأنسب؟' and q.options = '[{"label":"الاستمرار كما هو مع تحديث دراسة الطلب في المرحلة القادمة","score":2},{"label":"الاستمرار لأن الأداء ضمن الخطة والميزانية المعتمدتين","score":1},{"label":"عرض المبرر المحدث على اللجنة لتقرر الاستمرار أو التعديل","score":4},{"label":"تسريع التنفيذ لإطلاق الخدمة قبل أن يتراجع الطلب أكثر","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch3') or (q.text_ar = 'في مراجعة مرحلية: المشروع ضمن الموعد، لكن دراسة حديثة تظهر أن الطلب على الخدمة أقل بكثير مما بُني عليه المبرر. ما القرار الأنسب؟' and q.options = '[{"label":"الاستمرار كما هو مع تحديث دراسة الطلب في المرحلة القادمة","score":2},{"label":"الاستمرار لأن الأداء ضمن الخطة والميزانية المعتمدتين","score":1},{"label":"عرض المبرر المحدث على اللجنة لتقرر الاستمرار أو التعديل","score":4},{"label":"تسريع التنفيذ لإطلاق الخدمة قبل أن يتراجع الطلب أكثر","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch4'));
