    or (i.key = 'baseline-v5' and q.code = 'M-S6' and (q.text_ar = 'أبلغك المورد أن تسليم مكون رئيسي سيتأخر ستة أسابيع، وهذا الخطر مسجل مسبقًا مع خطة استجابة. ما أول خطوة؟' and q.options = '[{"label":"تفعيل خطة الاستجابة المسجلة وإبلاغ أصحاب القرار","score":4},{"label":"مطالبة المورد بخطة تعافٍ مكتوبة قبل تحديث الجدول","score":2},{"label":"تحديث الجدول بالتاريخ الجديد وذكره في التقرير الشهري","score":1},{"label":"مطالبة المورد بغرامة التأخير المنصوص عليها في العقد","score":1}]'::jsonb and q.chapter_key is not distinct from 'ch4'))
